INSERT INTO `email_templates` ( `uuid`, `template_code`, `name`, `subject`, `content`, `is_active`, `created_by`, `created_datetime`, `last_updated_by`, `last_updated_datetime`, `version`) VALUES ( 'da52b9a4-cdf3-403b-8cba-57c9bebbc9c5', 'welcome001', 'Welcome Email', 'Confirm your Account', '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Welcome Email</title>\n</head>\n<body style="font-family: \'Georgia\', serif; margin: 0; padding: 0; padding-bottom: 20px; background-color: transparent;">\n\n    <div style="width: 100%; margin: 0 auto; overflow: hidden; background-color: #ECF0F1; border-bottom: 2px solid #BDC3C7;">\n        <header style="background: #F1C40F; color: white; padding-top: 30px; min-height: 70px;">\n            <input type="checkbox" id="menu-btn" style="float: right; display: none;">\n            <label for="menu-btn" class="menu-icon" style="display: none;"></label>\n            <nav style="float: right; display: inline; margin-top: 10px; margin-right: 20px;">\n                <center>\n                    <h1 style="font-family: \'Georgia\', serif; color: #000000; padding-bottom: 10px; margin: 0;">Welcome to DMD jewellers, {userName}.</h1>\n                </center>\n            </nav>\n        </header>\n    </div>\n\n    <div style="width: 100%; margin: 0 auto; border: 2px solid #BDC3C7; padding: 10px;">\n        <p style="font-size: 16px; line-height: 1.5; margin-left: 20px;">\n            Dear {userName},<br/><br/>\n            Welcome to DMD! We\'re excited to have you join our community. Please confirm your account and establish your password by following the instructions below.<br/><br/>\n            <strong>Confirmation Code: </strong>{code}<br/><br/>\n            <strong>Instructions:</strong><br/>\n            1. Click on the following link to confirm your account: <a href="{link}" target="_blank" style="font-family: \'Georgia\', serif; color: #007BFF; text-decoration: underline;">Confirmation Link</a><br/>\n            2. Once confirmed, you\'ll be prompted to set your password securely.<br/>\n            3. Select a robust password that addresses our security guidelines.<br/>\n            4. If you encounter any challenges or have questions, reach out to our support team at:\n            <a href="mailto:support@dmd.com" style="font-family: \'Georgia\', serif; color: #007BFF; text-decoration: mailto:underline;">support@dmd.com</a>.<br/>\n            Thank you for choosing DMD. We\'re eager to support you every step of the way!<br/><br/>\n            Thank you,<br/>\n            The DMD Jewellers Team\n        </p>\n    </div>\n</body>\n</html>', 1, 'abhijit', '2023-12-19 17:12:13', 'abhijit', '2023-12-23 17:23:32', 1),
 ('ff36e515-4c64-4ded-ae9b-a1d52bff365d', 'regenerate001', 'Regenerate Confirmation Code', 'Your confirmation code', '<!DOCTYPE html>\r\n<html lang="en">\r\n<head>  \r\n  <meta charset="UTF-8">  \r\n    <meta name="viewport" content="width=device-width, initial-scale=1.0"> \r\n       <title>Email Confirmation</title>\r\n       </head>\r\n       <body style="font-family: Arial, Helvetica, sans-serif; margin: 0; padding: 0; background-color: #f4f4f4;"> \r\n          <div style="max-width: 600px; margin: 20px auto; background-color: #ffffff; padding: 20px; border-radius: 5px; box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);">  \r\n                <h2 style="color: #333333;">Email Confirmation</h2>  \r\n                 <p style="color: #666666;">Thank you for using our service. Your confirmation code is: <br/><br/> \r\n           <strong style="font-size: 24px; font-weight: bold; color: #4285f4;">{code}</strong></p>  \r\n             <p style="color: #666666;">Please use the code to complete your registration process.</p>   \r\n           <a href="{link}" target="_blank" style="display: inline-block; padding: 10px 20px; font-size: 16px; text-align: center; text-decoration: none; background-color: #4285f4; color: #ffffff; border-radius: 5px; cursor: pointer;">Confirm Now</a>    \r\n           <p style="color: #666666;">If you did not request this code, please ignore this email.</p>  \r\n                  </div>\r\n                  </body>\r\n                   </html>', 1, 'abhijit', '2023-12-19 17:12:29', 'abhijit', '2023-12-23 17:23:33', 1),
 ('2fd2b0c8-9fef-11ee-90ea-dd3b8d14bc74', 'changePassword001', 'Change Password', 'Password Change Confirmation', '<!DOCTYPE html>\r\n<html lang="en">\r\n\r\n<head>\r\n    <meta charset="UTF-8">\r\n    <meta http-equiv="X-UA-Compatible" content="IE=edge">\r\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\r\n    <title>Password Change Confirmation</title>\r\n</head>\r\n\r\n<body style="font-family: \'Arial\', sans-serif; line-height: 1.6; color: #333; background-color: #f5f5f5; margin: 0; padding: 0;">\r\n\r\n    <div style="max-width: 600px; margin: 20px auto; padding: 20px; background-color: #fff; border-radius: 5px; box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);">\r\n        <h2 style="color: #007BFF;">Password Change Confirmation</h2>\r\n        <p>Hello {userName},</p>\r\n        <p>Your password has been successfully changed.</p>\r\n        <p>If you did not make this change, please contact our support team immediately.</p>\r\n        <p>Thank you for using our service!</p>\r\n        <a href="{link}" target="_blank" style="display: inline-block; padding: 10px 20px; font-size: 16px; text-decoration: none; background-color: #007BFF; color: #fff; border-radius: 5px;">Visit Our Website</a>\r\n    </div>\r\n\r\n</body>\r\n\r\n</html>\r\n', 1, 'abhijit', '2023-12-21 16:23:34', 'abhijit', '2023-12-23 17:23:35', 1),
 ('1448ab24-a0ab-11ee-9113-de3d963a5e2b', 'setPassword001', 'Password Reset', 'Password reset', '<!DOCTYPE html>\r\n<html lang="en">\r\n\r\n<head>\r\n    <meta charset="UTF-8">\r\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\r\n</head>\r\n\r\n<body style="margin: 0; padding: 0; font-family: Arial, sans-serif; line-height: 1.6;">\r\n\r\n    <!-- Container -->\r\n    <div style="max-width: 600px; margin: 0 auto; padding: 20px;">\r\n\r\n        <!-- Header -->\r\n        <div style="background-color: #3498db; color: #ffffff; text-align: center; padding: 10px;">\r\n            <h1>Password Reset</h1>\r\n        </div>\r\n\r\n        <!-- Content -->\r\n        <div style="padding: 20px; background-color: #f4f4f4;">\r\n\r\n            <p>Hello {userName},</p>\r\n            <p>We received a request to reset your password. Click the button below to reset it:</p>\r\n            <p>\r\n                <a href="{link}" target="_blank" style="display: inline-block; padding: 10px 20px; background-color: #3498db; color: #ffffff; text-decoration: none; border-radius: 5px;">Reset Password</a>\r\n            </p>\r\n            <p>If you didn\'t request a password reset, please ignore this email.</p>\r\n\r\n        </div>\r\n\r\n        <!-- Footer -->\r\n        <div style="text-align: center; margin-top: 20px; color: #777;">\r\n            <p>Best regards,<br>DMD</p>\r\n        </div>\r\n\r\n    </div>\r\n\r\n</body>\r\n\r\n</html>\r\n', 1, 'abhijit', '2023-12-22 14:48:33', 'abhijit', '2023-12-23 17:23:37', 1),
 ('eea891ae-a16c-11ee-9130-de3e9c54d11b', 'emailVerification001', 'Email Confirmation', 'Email Verification', '<!DOCTYPE html>\r\n<html lang="en">\r\n<head>\r\n    <meta charset="UTF-8">\r\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\r\n    <title>Email Verification</title>\r\n</head>\r\n<body style="font-family: Arial, sans-serif; margin: 0; padding: 0; background-color: #f4f4f4;">\r\n\r\n    <div style="width: 100%; max-width: 600px; margin: 0 auto; background-color: #ffffff; padding: 20px; box-sizing: border-box; border-radius: 5px; box-shadow: 0 0 10px rgba(0, 0, 0, 0.1); margin-top: 20px;">\r\n\r\n        <h2 style="color: #333333;">Email Verification</h2>\r\n\r\n        <p style="color: #555555;">Dear user,</p>\r\n\r\n        <p style="color: #555555;">Thank you for signing up. To verify your email, please click the following link:</p>\r\n\r\n        <a style="display: inline-block; padding: 10px 20px; text-decoration: none; background-color: #4caf50; color: #ffffff; border-radius: 5px;" href="{link}">Verify Email</a>\r\n\r\n        <p style="color: #555555;">Alternatively, open the following url in your browser:</p>\r\n\r\n        <p style="color: #555555;">https://example.com/verify?token={code}</p>\r\n\r\n        <p style="color: #555555;">This verification link will expire in 24 hours.</p>\r\n\r\n        <div style="margin-top: 20px; text-align: center; color: #888888;">\r\n            <p>If you did not sign up for this service, please ignore this email.</p>\r\n        </div>\r\n\r\n    </div>\r\n\r\n</body>\r\n</html>\r\n', 1, 'abhijit', '2023-12-23 14:21:32', 'abhijit', '2023-12-23 17:23:38', 1),
 ('74cf60e7-a223-11ee-91a5-df44b5bf9dd4', 'emailUpdateVerification001', 'Email Update Verification', 'Email Address Update', '<!DOCTYPE html>\r\n<html lang="en">\r\n<head>\r\n    <meta charset="UTF-8">\r\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\r\n    <title>Email Update Verification</title>\r\n</head>\r\n<body style="font-family: \'Arial\', sans-serif; margin: 0; padding: 0; background-color: #f4f4f4; color: #333;">\r\n\r\n    <div style="max-width: 600px; margin: 20px auto; background-color: #fff; padding: 20px; border-radius: 5px; box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);">\r\n        <h2 style="color: #333;">Email Address Update</h2>\r\n        <p>You are just a step away from updating your email address.</p>\r\n        <p>We are sharing a one-time use verification code (OTP) for this request.</p>\r\n        \r\n        <div style="font-size: 24px; font-weight: bold; color: #3498db;">Verification Code (OTP): {code}</div>\r\n        <p>Validity: 10 minutes</p>\r\n        <p style="color: #e74c3c; font-weight: bold;">Important note:</p>\r\n        <p>Please do not share this code with anyone for the security of your DMD account.</p>\r\n\r\n        <p>Thanks,<br>DMD</p>\r\n    </div>\r\n\r\n</body>\r\n</html>\r\n', 1, 'abhijit', '2023-12-24 11:42:46', 'abhijit', '2023-12-24 11:44:11', 1);
